<style>
:root{--bg:#070408;--panel:rgba(16,10,15,.82);--rose:#ee1478;--aqua:#78ddd5;--gold:#d3b77c;--text:#f1e6eb;--muted:#a9969f;--line:rgba(255,255,255,.11);--good:#78ddd5;--warn:#d3b77c}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--text);font-family:Jost,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.app{position:relative;width:100%;height:100%;overflow:hidden;background:radial-gradient(circle at 50% 50%,rgba(111,16,66,.18),transparent 38%),#070408}.grid{position:absolute;inset:0;background-image:linear-gradient(rgba(211,183,124,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(211,183,124,.025) 1px,transparent 1px);background-size:80px 80px;mask-image:radial-gradient(circle,#000,transparent 82%)}
.dna{position:absolute;inset:-12%;pointer-events:none;opacity:.82;filter:drop-shadow(0 0 10px rgba(238,20,120,.18))}.strand{position:absolute;width:56%;height:22%;border:1px solid rgba(238,20,120,.34);border-radius:50%;transform:rotate(-13deg);animation:drift 12s ease-in-out infinite alternate}.strand:before,.strand:after{content:"";position:absolute;inset:18%;border:1px dotted rgba(120,221,213,.26);border-radius:50%}.s1{left:-8%;top:5%}.s2{right:-10%;top:25%;transform:rotate(18deg);animation-delay:-5s}.s3{left:15%;bottom:2%;width:72%;transform:rotate(-4deg);animation-delay:-8s}.nodes{position:absolute;inset:0;background-image:radial-gradient(circle,rgba(238,20,120,.85) 0 2px,transparent 3px),radial-gradient(circle,rgba(211,183,124,.7) 0 1px,transparent 2px);background-size:120px 86px,170px 140px;animation:floatnodes 18s linear infinite}.pulse{position:absolute;width:10px;height:10px;border-radius:50%;background:var(--rose);box-shadow:0 0 22px var(--rose);animation:travel 9s linear infinite}.p1{top:18%;left:4%}.p2{top:52%;right:8%;animation-delay:-3s}.p3{bottom:12%;left:28%;animation-delay:-6s}@keyframes drift{to{transform:translate3d(3vw,2vh,0) rotate(11deg) scale(1.05)}}@keyframes floatnodes{to{background-position:120px 86px,-170px 140px}}@keyframes travel{50%{transform:translate(55vw,22vh) scale(1.6)}100%{transform:translate(90vw,-8vh) scale(.6)}}
.brand{position:absolute;z-index:20;top:22px;left:28px;display:flex;gap:12px;align-items:baseline;letter-spacing:.18em;text-transform:uppercase;font-size:11px}.brand b{color:var(--rose);font-weight:500}.brand span{color:var(--aqua)}.status{position:absolute;z-index:20;top:22px;right:28px;font-size:11px;letter-spacing:.08em;color:var(--muted)}.status i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--aqua);box-shadow:0 0 10px var(--aqua);margin-right:6px}
.deck{position:absolute;inset:0}.slide{position:absolute;inset:0;padding:78px 7vw 74px;display:grid;place-items:center;opacity:0;visibility:hidden;transform:translateY(18px);transition:.55s ease;overflow:auto}.slide.active{opacity:1;visibility:visible;transform:none}.content{width:min(1180px,100%);max-height:calc(100vh - 160px)}.kicker{margin:0 0 10px;color:var(--aqua);font-size:11px;letter-spacing:.24em;text-transform:uppercase}.title{font-family:"Cormorant Garamond",serif;font-weight:300;font-size:clamp(38px,5vw,68px);line-height:.98;margin:0 0 14px}.title em{font-style:normal;color:var(--rose)}.sub{font-family:"Cormorant Garamond",serif;font-size:20px;color:var(--muted);max-width:760px;line-height:1.4;margin:0 0 28px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.015));border:1px solid var(--line);border-radius:18px;padding:18px;backdrop-filter:blur(9px)}.card b{display:block;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--aqua);margin-bottom:8px}.metric{font-family:"Cormorant Garamond",serif;font-size:42px;color:var(--text)}.metric small{font-family:Jost;font-size:11px;color:var(--muted)}.bar{height:6px;border-radius:10px;background:rgba(255,255,255,.08);overflow:hidden;margin-top:10px}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--rose),var(--aqua));width:0;transition:width .8s ease}.group-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;max-height:58vh;overflow:auto;padding-right:6px}.group{border:1px solid var(--line);border-radius:18px;background:rgba(9,7,10,.72);padding:16px}.group h3{font-family:"Cormorant Garamond";font-size:24px;font-weight:400;margin:0 0 12px}.field{display:grid;grid-template-columns:1fr 150px 72px;gap:8px;align-items:center;padding:7px 0;border-top:1px solid rgba(255,255,255,.06)}.field:first-of-type{border-top:0}.field label{font-size:12px;color:#dbcbd2}.field input,.field select{width:100%;background:#0d090d;border:1px solid var(--line);color:var(--text);border-radius:10px;padding:8px 9px}.unit{font-size:10px;color:var(--muted);text-align:right}.save{margin-top:14px;display:flex;align-items:center;gap:10px}.btn{border:1px solid rgba(238,20,120,.45);background:rgba(238,20,120,.13);color:#fff;border-radius:999px;padding:10px 18px;cursor:pointer}.btn.primary{background:var(--rose);border-color:var(--rose)}.btn:hover{filter:brightness(1.12)}.table{border:1px solid var(--line);border-radius:16px;overflow:auto;max-height:56vh;background:rgba(7,4,8,.72)}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.06);vertical-align:top}th{position:sticky;top:0;background:#100a0f;color:var(--aqua);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.tag{display:inline-block;padding:4px 7px;border-radius:999px;border:1px solid var(--line);font-size:9px;text-transform:uppercase;letter-spacing:.06em}.tag.pass{color:var(--aqua)}.tag.blocked{color:var(--gold)}.report-upload{display:flex;gap:9px;flex-wrap:wrap;margin:12px 0}.report-upload select,.report-upload input{background:#0d090d;border:1px solid var(--line);color:#fff;border-radius:10px;padding:8px}.nav{position:absolute;z-index:30;left:28px;right:28px;bottom:20px;display:flex;justify-content:space-between;align-items:center}.nav .center{font-size:10px;letter-spacing:.14em;color:var(--muted)}.nav button{width:40px;height:40px;border-radius:50%;border:1px solid var(--line);background:rgba(0,0,0,.35);color:#fff;cursor:pointer}.err{padding:12px;border:1px solid rgba(238,20,120,.35);border-radius:12px;color:#f5b4d0}.muted{color:var(--muted)}
@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.group-grid{grid-template-columns:1fr}.field{grid-template-columns:1fr 120px 58px}.content{max-height:calc(100vh - 150px)}.slide{padding:72px 20px 68px}.brand{left:18px}.status{right:18px}.nav{left:18px;right:18px}}
@media(prefers-reduced-motion:reduce){.strand,.nodes,.pulse{animation:none}.slide{transition:none}}
</style>
