<body>
<div class="app">
  <div class="grid"></div><div class="dna"><div class="strand s1"></div><div class="strand s2"></div><div class="strand s3"></div><div class="nodes"></div><i class="pulse p1"></i><i class="pulse p2"></i><i class="pulse p3"></i></div>
  <div class="brand"><b>I Love My Body</b><span>Self Care Hospital</span></div>
  <div class="status" id="dbStatus"><i></i>Connecting to database…</div>
  <main class="deck" id="deck">
    <section class="slide active"><div class="content"><p class="kicker">ILMB REPORT 001 · LIVE DATABASE</p><h1 class="title">Psoriasis.<br><em>Baseline first. Personalise continuously.</em></h1><p class="sub" id="intro">Loading the patient-linked psoriasis model from the ILMB database…</p><div class="cards" id="summaryCards"></div></div></section>
    <section class="slide"><div class="content"><p class="kicker">PERSONALISED INPUT GRAPH</p><h2 class="title">Every governed field.<br><em>One patient overlay.</em></h2><p class="sub">Edit what you know. Each save creates a new source observation; older observations remain preserved.</p><div class="group-grid" id="fieldGroups"></div><div class="save"><button class="btn primary" id="saveFields">Save changes to DB</button><span class="muted" id="saveMsg"></span></div></div></section>
    <section class="slide"><div class="content"><p class="kicker">REPORTS · LABS · PHOTOS</p><h2 class="title">Add information.<br><em>Increase precision.</em></h2><p class="sub">Existing reports already linked to this patient appear below. Uploading more information refines the model; it does not erase the baseline plan.</p><form class="report-upload" id="uploadForm"><select name="document_type"><option value="laboratory_report">Laboratory report</option><option value="prescription">Prescription</option><option value="imaging_report">Imaging / photograph report</option><option value="food_log">Food log</option><option value="other">Other clinical report</option></select><input type="file" name="file" accept="application/pdf,image/*" required><button class="btn primary" type="submit">Upload securely</button><span id="uploadMsg" class="muted"></span></form><div class="table"><table><thead><tr><th>Date</th><th>Report</th><th>Type</th><th>Extraction</th><th>Review</th></tr></thead><tbody id="docRows"></tbody></table></div></div></section>
    <section class="slide"><div class="content"><p class="kicker">TREATMENT + SAFETY</p><h2 class="title">What has been used.<br><em>What changed.</em></h2><p class="sub">Medication history, exposure and adverse events are read from the patient database—not from the presentation.</p><div class="cards" id="medicineCards"></div><div class="table" style="margin-top:14px"><table><thead><tr><th>Medicine / exposure</th><th>Dose / schedule</th><th>Verification</th><th>Reason / period</th></tr></thead><tbody id="medRows"></tbody></table></div></div></section>
    <section class="slide"><div class="content"><p class="kicker">CALCULATION READINESS</p><h2 class="title">Measured values in.<br><em>Governed calculations out.</em></h2><p class="sub">Parameters and release gates are read from the psoriasis model. Missing coefficients remain missing; blocked calculations stay blocked.</p><div class="cards" id="formulaCards"></div><div class="table" style="margin-top:14px"><table><thead><tr><th>Gate</th><th>Status</th><th>Reason</th><th>Checked</th></tr></thead><tbody id="gateRows"></tbody></table></div></div></section>
    <section class="slide"><div class="content"><p class="kicker">END OF REPORT 001</p><h2 class="title">Need → State → Choice → Consequence ↺</h2><p class="sub">The report is now a live database view. As reports, observations, lifestyle, food and treatment data are added, this same report recalculates its personalisation layer. Recipe auto-create and the meal plan are downstream consumers of these governed requirements—not hard-coded content.</p><div class="cards"><div class="card"><b>Next engine</b><div class="metric">Food</div><span class="muted">requirements → food chemistry</span></div><div class="card"><b>Then</b><div class="metric">Recipes</div><span class="muted">constraint-aware auto-create</span></div><div class="card"><b>Close</b><div class="metric">Meal plan</div><span class="muted">daily totals + remaining gaps</span></div><div class="card"><b>Loop</b><div class="metric">Review</div><span class="muted">new data → recalculation</span></div></div></div></section>
  </main>
  <div class="nav"><button id="prev" aria-label="Previous">←</button><div class="center"><span id="count">1 / 6</span> · LIVE REPORT</div><button id="next" aria-label="Next">→</button></div>
</div>
<script>
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let data=null,slide=0; const slides=$$('.slide');
function show(n){slide=(n+slides.length)%slides.length;slides.forEach((x,i)=>x.classList.toggle('active',i===slide));$('#count').textContent=`${slide+1} / ${slides.length}`}
$('#prev').onclick=()=>show(slide-1);$('#next').onclick=()=>show(slide+1);addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' ')show(slide+1);if(e.key==='ArrowLeft')show(slide-1)});
function esc(v){return String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function valFor(code){const o=data?.latest_observations?.[code];return o?.value_number??o?.value_text??''}
async function load(){try{const r=await fetch('ilmb-report-001-api.php?action=bootstrap',{credentials:'same-origin'});data=await r.json();if(!data.ok)throw new Error(data.error||'Load failed');$('#dbStatus').innerHTML='<i></i>Live database connected';render()}catch(e){$('#dbStatus').textContent='Database connection failed';$('#intro').innerHTML=`<span class="err">${esc(e.message)}</span>`}}
function render(){const c=data.completeness||{};$('#intro').textContent=`${data.case.label} · ${data.report.disease} · ${c.known_fields} of ${c.defined_fields} governed fields currently have patient observations.`;$('#summaryCards').innerHTML=`<div class="card"><b>Patient</b><div class="metric">${esc(data.case.label)}</div><small>${esc(data.case.age||'Age not exposed')} · ${esc(data.case.sex||'Sex not exposed')}</small></div><div class="card"><b>Known fields</b><div class="metric">${c.known_fields}<small> / ${c.defined_fields}</small></div><div class="bar"><span style="width:${c.personalisation_percent}%"></span></div></div><div class="card"><b>Required known</b><div class="metric">${c.release_required_known}<small> / ${c.release_required_fields}</small></div></div><div class="card"><b>Personalisation</b><div class="metric">${c.personalisation_percent}<small>%</small></div><small>More data refines; it does not erase baseline planning.</small></div>`;
 const groups={};(data.input_definitions||[]).forEach(d=>(groups[d.category_code]??=[]).push(d));$('#fieldGroups').innerHTML=Object.entries(groups).map(([g,defs])=>`<div class="group"><h3>${esc(g.replaceAll('_',' '))}</h3>${defs.map(d=>{const current=valFor(d.input_code);const unit=d.canonical_unit_code||'';let control;if(d.value_domain==='BOOLEAN')control=`<select data-code="${esc(d.input_code)}"><option value=""></option><option ${current==='true'?'selected':''}>true</option><option ${current==='false'?'selected':''}>false</option></select>`;else control=`<input data-code="${esc(d.input_code)}" data-domain="${esc(d.value_domain)}" value="${esc(current)}" placeholder="${d.release_required==1?'Required / useful':'Optional'}">`;return `<div class="field"><label>${esc(d.label)}</label>${control}<span class="unit">${esc(unit)}</span></div>`}).join('')}</div>`).join('');
 $('#docRows').innerHTML=(data.documents||[]).map(d=>`<tr><td>${esc(d.document_date||d.created_at||'')}</td><td>${esc(d.original_filename)}</td><td>${esc(d.document_type)}</td><td>${esc(d.extraction_status)}</td><td>${esc(d.human_review_status)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">No reports linked yet.</td></tr>';
 const medCount=(data.medicines||[]).length, expCount=(data.medicine_exposures||[]).length, aeCount=(data.adverse_events||[]).length;$('#medicineCards').innerHTML=`<div class="card"><b>Reported medicines</b><div class="metric">${medCount}</div></div><div class="card"><b>Structured exposures</b><div class="metric">${expCount}</div></div><div class="card"><b>Adverse events</b><div class="metric">${aeCount}</div></div><div class="card"><b>Source</b><div class="metric">DB</div><small>Patient-linked records</small></div>`;$('#medRows').innerHTML=[...(data.medicines||[]).map(m=>`<tr><td>${esc(m.reported_name)}</td><td>${esc([m.strength_text,m.dose_text,m.frequency_text].filter(Boolean).join(' · '))}</td><td>${esc(m.verification_status)}</td><td>${esc(m.reason_text)}</td></tr>`),...(data.medicine_exposures||[]).map(m=>`<tr><td>${esc(m.medicine_name_as_recorded)}</td><td>${esc([m.dose_value,m.dose_unit,m.schedule_text].filter(Boolean).join(' '))}</td><td>${esc(m.verification_status)}</td><td>${esc([m.start_at,m.end_at].filter(Boolean).join(' → '))}</td></tr>`)].join('')||'<tr><td colspan="4" class="muted">No medicine records linked yet.</td></tr>';
 const f=data.formula_summary||{}; const params=Object.values(data.parameters||{});$('#formulaCards').innerHTML=`<div class="card"><b>Active parameters</b><div class="metric">${f.parameters??0}</div></div><div class="card"><b>Verified formulas</b><div class="metric">${f.verified_formulas??0}</div></div><div class="card"><b>Formula inputs</b><div class="metric">${f.formula_inputs??0}</div></div><div class="card"><b>Psoriasis parameters</b><div class="metric">${params.length}</div><small>${params.filter(x=>x.value_number!==null&&x.value_number!==undefined).length} have patient values</small></div>`;$('#gateRows').innerHTML=(data.release_gates||[]).map(g=>`<tr><td>${esc(g.gate_code)}</td><td><span class="tag ${String(g.gate_status).toLowerCase()}">${esc(g.gate_status)}</span></td><td>${esc(g.reason_text)}</td><td>${esc(g.checked_at)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No model gates registered.</td></tr>'}
$('#saveFields').onclick=async()=>{const observations=$$('#fieldGroups input[data-code],#fieldGroups select[data-code]').filter(el=>String(el.value).trim()!=='').map(el=>({input_code:el.dataset.code,value:el.value,unit_code:el.closest('.field').querySelector('.unit')?.textContent||null}));$('#saveMsg').textContent='Saving…';try{const r=await fetch('ilmb-report-001-api.php?action=save-observations',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({observations})});const j=await r.json();if(!j.ok)throw new Error(j.error||'Save failed');$('#saveMsg').textContent=`${j.saved} observations saved. Reloading…`;await load()}catch(e){$('#saveMsg').textContent=e.message}};
$('#uploadForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);$('#uploadMsg').textContent='Uploading…';try{const r=await fetch('api.php?action=upload',{method:'POST',body:fd,credentials:'same-origin'});const j=await r.json();if(!j.ok)throw new Error(j.error||'Upload failed');$('#uploadMsg').textContent='Report linked to patient.';e.currentTarget.reset();await load()}catch(e2){$('#uploadMsg').textContent=e2.message}};
load();
</script>
</body></html>
